inputs = ['jdbih', 'ik', 'auuyh', 'hkg', 'cf']
outputs = ['idbxkh', 'xkk', 'iuuyh', 'hkg', 'cf']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Let's see the differences
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))

        # Check if there's additional text at the end
        if len(outp) > len(inp):
            added = outp[len(inp):]
            print(f"  Added at end: '{added}'")

        if diff_positions:
            print(f"  Differences at positions: {diff_positions}")
        print()

